INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8822, 'ចម្ងាយរវាងចំណុច \(A(0, 0)\) និង \(B(3, 4)\) ស្មើ ៖', NULL, '["\\(12\\)", "\\(7\\)", "\\(25\\)", "\\(5\\)"]', 3, NULL, 2, 'mcq', '\(d = \sqrt{3^2 + 4^2} = \sqrt{9 + 16} = \sqrt{25} = 5\)។', 'ប្លង់កូអរដោនេនិងក្រាប', 'medium', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8823, 'ចម្ងាយរវាងចំណុច \(M(1, 2)\) និង \(N(4, 6)\) ស្មើ ៖', NULL, '["\\(5\\)", "\\(4\\)", "\\(25\\)", "\\(7\\)"]', 0, NULL, 2, 'mcq', '\(MN = \sqrt{(4-1)^2 + (6-2)^2} = \sqrt{3^2 + 4^2} = 5\)។', 'ប្លង់កូអរដោនេនិងក្រាប', 'medium', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8824, 'ក្នុងរូប បន្ទាត់កាត់តាម \((0, 1)\) និង \((1, 3)\) មានសមីការ ៖', 'g8-5c707fe810.svg', '["\\(y = x + 1\\)", "\\(y = 2x + 1\\)", "\\(y = 3x + 1\\)", "\\(y = 2x - 1\\)"]', 1, NULL, 2, 'mcq', 'មេគុណ \(a = \dfrac{3 - 1}{1 - 0} = 2\) និងកាត់ \(y\) ត្រង់ \(1 \Rightarrow y = 2x + 1\)។', 'ប្លង់កូអរដោនេនិងក្រាប', 'medium', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8825, 'សមីការបន្ទាត់កាត់តាមចំណុច \(A(0, 3)\) និង \(B(3, 6)\) គឺ ៖', NULL, '["\\(y = -x + 3\\)", "\\(y = x - 3\\)", "\\(y = x + 3\\)", "\\(y = 2x + 3\\)"]', 2, NULL, 3, 'mcq', '\(a = \dfrac{6-3}{3-0} = 1 \Rightarrow y = x + 3\)។', 'ប្លង់កូអរដោនេនិងក្រាប', 'hard', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8826, 'ផ្ទៃក្រឡាត្រីកោណកែងដែលបង្កើតឡើងដោយបន្ទាត់ \(y = -2x + 4\) ជាមួយអ័ក្សទាំងពីរគឺ ៖', NULL, '["\\(2\\ \\text{ឯកតាផ្ទៃ}\\)", "\\(4\\ \\text{ឯកតាផ្ទៃ}\\)", "\\(6\\ \\text{ឯកតាផ្ទៃ}\\)", "\\(8\\ \\text{ឯកតាផ្ទៃ}\\)"]', 1, NULL, 3, 'mcq', 'កាត់ \(x\) ត្រង់ \(2\) និងកាត់ \(y\) ត្រង់ \(4 \Rightarrow S = \dfrac{1}{2} \times 2 \times 4 = 4\)។', 'ប្លង់កូអរដោនេនិងក្រាប', 'hard', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8827, 'ក្នុងចំណោមចំណុច \(A(0, 5), B(1, 4), D(3, 0)\) ចំណុចទាំងបីនេះ ៖', NULL, '["ឋិតលើបន្ទាត់តែមួយ", "រត់ត្រង់ជួរគ្នា", "មិនរត់ត្រង់ជួរគ្នាទេ", "បង្កើតបានត្រីកោណសម័ង្ស"]', 2, NULL, 3, 'mcq', '\(m_{AB} = \dfrac{4-5}{1-0} = -1\) តែ \(m_{BD} = \dfrac{0-4}{3-1} = -2 \neq -1\) ដូចនេះមិនរត់ត្រង់ជួរទេ។', 'ប្លង់កូអរដោនេនិងក្រាប', 'hard', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8828, 'សមីការបន្ទាត់កាត់តាមចំណុច \(A(0, 4)\) និង \(B(2, 2)\) គឺ ៖', NULL, '["\\(y = -x + 4\\)", "\\(y = -x - 4\\)", "\\(y = x + 4\\)", "\\(y = -2x + 4\\)"]', 0, NULL, 3, 'mcq', '\(a = \dfrac{2-4}{2-0} = -1 \Rightarrow y = -x + 4\)។', 'ប្លង់កូអរដោនេនិងក្រាប', 'hard', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8829, 'ផ្ទៃក្រឡាត្រីកោណដែលមានកំពូល \(O(0, 0), A(6, 0)\) និង \(B(0, 5)\) ស្មើ ៖', NULL, '["\\(30\\)", "\\(15\\)", "\\(18\\)", "\\(11\\)"]', 1, NULL, 3, 'mcq', '\(S = \dfrac{1}{2} \times 6 \times 5 = 15\) ឯកតាផ្ទៃ។', 'ប្លង់កូអរដោនេនិងក្រាប', 'hard', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8830, 'តម្លៃនៃ \(m\) ដើម្បីឱ្យបន្ទាត់ \(y = mx + 3\) ស្របនឹងបន្ទាត់ \(2x - y + 5 = 0\) គឺ ៖', NULL, '["\\(m = \\dfrac{1}{2}\\)", "\\(m = 2\\)", "\\(m = -2\\)", "\\(m = 5\\)"]', 1, NULL, 3, 'mcq', '\(2x - y + 5 = 0 \Rightarrow y = 2x + 5 \Rightarrow m = 2\)។', 'ប្លង់កូអរដោនេនិងក្រាប', 'hard', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8831, 'បន្ទាត់ \(y = -3x + 6\) និងបន្ទាត់ \(y = 2x + 1\) ប្រសព្វគ្នាត្រង់ចំណុច ៖', NULL, '["\\((0, 6)\\)", "\\((2, 0)\\)", "\\((1, 5)\\)", "\\((1, 3)\\)"]', 3, NULL, 3, 'mcq', '\(-3x + 6 = 2x + 1 \Rightarrow 5x = 5 \Rightarrow x = 1 \Rightarrow y = 3\) គឺ \((1, 3)\)។', 'ប្លង់កូអរដោនេនិងក្រាប', 'hard', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8832, 'ក្រាបបង្ហាញប្រវែងស្រមោលបង្គោលមួយពីម៉ោង 7h ដល់ 17h។ តាមក្រាប ស្រមោលមានប្រវែងខ្លីបំផុតនៅវេលាម៉ោង ៖', 'g8-9fd123fb39.svg', '["ម៉ោង 17 ល្ងាច", "ម៉ោង 7 ព្រឹក", "ម៉ោង 10 ព្រឹក", "ម៉ោង 12 ថ្ងៃត្រង់"]', 3, NULL, 3, 'mcq', 'នៅពេលថ្ងៃត្រង់ ព្រះអាទិត្យនៅត្រង់ក្បាល បង្កើតស្រមោលខ្លីបំផុត។', 'ប្លង់កូអរដោនេនិងក្រាប', 'pisa', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8833, 'តាក់ស៊ីមួយគិតថ្លៃសេវា \(y = 2\,000x + 5\,000\) (រៀល) ដែល \(x\) ជាចម្ងាយ (km)។ បើអ្នកដំណើរជិះចម្ងាយ \(12\ \text{km}\) ថ្លៃឈ្នួលត្រូវបង់គឺ ៖', NULL, '["\\(24\\,000\\ \\text{រៀល}\\)", "\\(29\\,000\\ \\text{រៀល}\\)", "\\(19\\,000\\ \\text{រៀល}\\)", "\\(34\\,000\\ \\text{រៀល}\\)"]', 1, NULL, 3, 'mcq', '\(y = 2\,000(12) + 5\,000 = 24\,000 + 5\,000 = 29\,000\ \text{រៀល}\)។', 'ប្លង់កូអរដោនេនិងក្រាប', 'pisa', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8834, 'ក្រាបកម្ពស់តាមអាយុបង្ហាញថា សិស្សម្នាក់មានកម្ពស់ \(130\ \text{cm}\) នៅអាយុ ១០ ឆ្នាំ និង \(170\ \text{cm}\) នៅអាយុ ១៨ ឆ្នាំ។ កំណើនកម្ពស់មធ្យមក្នុងមួយឆ្នាំគឺ ៖', NULL, '["\\(5\\ \\text{cm/ឆ្នាំ}\\)", "\\(4\\ \\text{cm/ឆ្នាំ}\\)", "\\(8\\ \\text{cm/ឆ្នាំ}\\)", "\\(6\\ \\text{cm/ឆ្នាំ}\\)"]', 0, NULL, 3, 'mcq', '\(\dfrac{170 - 130}{18 - 10} = \dfrac{40}{8} = 5\ \text{cm/ឆ្នាំ}\)។', 'ប្លង់កូអរដោនេនិងក្រាប', 'pisa', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8835, 'ក្រាបសីតុណ្ហភាពប្រចាំថ្ងៃបង្ហាញថា សីតុណ្ហភាពអប្បបរមា \(22^\circ\text{C}\) នៅម៉ោង 5h ព្រឹក និងអតិបរមា \(34^\circ\text{C}\) នៅម៉ោង 14h រសៀល។ គម្លាតសីតុណ្ហភាពក្នុងថ្ងៃនោះគឺ ៖', NULL, '["\\(10^\\circ\\text{C}\\)", "\\(56^\\circ\\text{C}\\)", "\\(12^\\circ\\text{C}\\)", "\\(14^\\circ\\text{C}\\)"]', 2, NULL, 3, 'mcq', '\(34^\circ\text{C} - 22^\circ\text{C} = 12^\circ\text{C}\)។', 'ប្លង់កូអរដោនេនិងក្រាប', 'pisa', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8836, 'អាងទឹកមួយមានទឹក 500 L កំពុងបង្ហូរចេញតាមសមីការ \(V = 500 - 25t\) ដែល \(t\) គិតជា នាទី (mn)។ រយៈពេលដើម្បីបង្ហូរទឹកអស់ពីអាងគឺ ៖', NULL, '["\\(25\\ \\text{mn}\\)", "\\(15\\ \\text{mn}\\)", "\\(50\\ \\text{mn}\\)", "\\(20\\ \\text{mn}\\)"]', 3, NULL, 3, 'mcq', 'ទឹកអស់ពីអាងពេល \(V = 0 \Rightarrow 500 - 25t = 0 \Rightarrow t = 20\ \text{mn}\)។', 'ប្លង់កូអរដោនេនិងក្រាប', 'pisa', 1, '8', 'ប្លង់កូអរដោនេនិងក្រាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8837, 'គេឱ្យចំណុច \(A(3, 5), B(-3, 4), C(-4, -3), D(2, -3)\) ក្នុងប្លង់កូអរដោនេ។ ចូរបញ្ជាក់កាដ្រង់ដែលចំណុចនីមួយៗស្ថិតនៅ។', NULL, '[]', 0, NULL, 5, 'writing', '\(A(3, 5)\) ៖ អាប់ស៊ីសវិជ្ជមាន អរដោនេវិជ្ជមាន ឋិតក្នុងកាដ្រង់ទី I (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8838, 'គេឱ្យសមីការបន្ទាត់ \(y = 2x + 4\)។ ក. រកចំណុចប្រសព្វជាមួយអ័ក្ស \(y''y\)។ ខ. រកចំណុចប្រសព្វជាមួយអ័ក្ស \(x''x\)។ គ. សរសេរតារាងតម្លៃលេខពី \(x = -2, 0, 1\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ប្រសព្វ \(y''y \Rightarrow x = 0 \Rightarrow y = 4 \Rightarrow (0, 4)\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8839, 'គេឱ្យសមីការ \(3x + y = 2\)។ ក. សរសេរសមីការជាទម្រង់ \(y = ax + b\)។ ខ. បង្ហាញមេគុណប្រាប់ទិស។ គ. រកតម្លៃ \(y\) ចំពោះ \(x = 0, 1, 2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(y = -3x + 2\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8840, 'គេឱ្យសមីការ \(x - 3 = -3y\)។ ក. សរសេរ \(y\) ជាអនុគមន៍នៃ \(x\)។ ខ. រកកូអរដោនេ ៣ ចំណុចនៅលើបន្ទាត់នេះ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(-3y = x - 3 \Rightarrow 3y = -x + 3\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8841, 'គណនាចម្ងាយរវាងចំណុច \(A(4, 5)\) និង \(B(8, 2)\) ក្នុងប្លង់កូអរដោនេ។', NULL, '[]', 0, NULL, 5, 'writing', 'រូបមន្តចម្ងាយ ៖ \(AB = \sqrt{(x_B - x_A)^2 + (y_B - y_A)^2}\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8842, 'គេឱ្យបន្ទាត់បួន ៖ \(y = 2x, y = 2x+1, y = 2x-3, y = 2x+2\)។ ក. រកមេគុណប្រាប់ទិសនៃបន្ទាត់នីមួយៗ។ ខ. ទាញសេចក្តីសន្និដ្ឋានអំពីទីតាំងនៃបន្ទាត់ទាំងបួនក្នុងប្លង់។', 'g8-45e16b0fc1.svg', '[]', 0, NULL, 5, 'writing', 'ក. បន្ទាត់នីមួយៗមានមេគុណមុខ \(x\) ស្មើគ្នា គឺ \(a = 2\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8843, 'គណនាផ្ទៃក្រឡាត្រីកោណកែងដែលបង្កើតដោយបន្ទាត់ \(y = -2x + 4\) ជាមួយអ័ក្សកូអរដោនេទាំងពីរ។', NULL, '[]', 0, NULL, 5, 'writing', 'រកចំណុចប្រសព្វជាមួយអ័ក្សអរដោនេ ៖ \(x = 0 \Rightarrow y = 4 \Rightarrow A(0, 4)\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8844, 'គេឱ្យចំណុច \(A(1, 2), B(2, 4), C(3, 6)\)។ ក. រកមេគុណប្រាប់ទិស \(m_{AB}\) និង \(m_{BC}\)។ ខ. បញ្ជាក់ថាតើចំណុចទាំងបីរត់ត្រង់ជួរគ្នាឬទេ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(m_{AB} = \dfrac{4 - 2}{2 - 1} = \dfrac{2}{1} = 2\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8845, 'រកសមីការបន្ទាត់កាត់តាមចំណុច \(A(0, 3)\) និង \(B(3, 6)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សមីការទូទៅ ៖ \(y = ax + b\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8846, 'ក្រាបកម្ពស់បង្ហាញថាសិស្សម្នាក់មានកម្ពស់ \(130\ \text{cm}\) នៅអាយុ ១០ ឆ្នាំ និង \(170\ \text{cm}\) នៅអាយុ ១៨ ឆ្នាំ។ ក. រកអត្រាកំណើនកម្ពស់មធ្យមក្នុងមួយឆ្នាំ។ ខ. សរសេរសមីការបន្ទាត់កម្ពស់ \(h\) តាមអាយុ \(t\)។ គ. ប៉ាន់ស្មានកម្ពស់នៅអាយុ ១៤ ឆ្នាំ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. អត្រាកំណើន ៖ \(a = \dfrac{170 - 130}{18 - 10} = \dfrac{40}{8} = 5\ \text{cm/ឆ្នាំ}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8847, 'តាក់ស៊ីមួយគិតថ្លៃសេវា \(y = 2\,000x + 5\,000\) (រៀល) ដែល \(x\) ជាចម្ងាយ (km)។ ក. ប្រាប់អត្ថន័យនៃលេខ 5 000 និងលេខ 2 000។ ខ. គណនាថ្លៃឈ្នួលបើជិះបាន 15 km។ គ. បើអ្នកដំណើរមានប្រាក់ 45 000 រៀល រកចម្ងាយអតិបរមាដែលអាចជិះបាន។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(5\,000\) ជាថ្លៃសេវាចាប់ផ្តើមដំបូង ; \(2\,000\) ជាថ្លៃឈ្នួលក្នុង 1 km (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8848, 'អាងទឹកមួយមានទឹក 500 L ត្រូវបានបង្ហូរចេញតាមសមីការ \(V = 500 - 25t\) (\(t\) គិតជា នាទី)។ ក. រកបរិមាណទឹកនៅពេល \(t = 0\)។ ខ. រកបរិមាណទឹកក្រោយបង្ហូរបាន 10 នាទី។ គ. រករយៈពេលដើម្បីបង្ហូរទឹកអស់ពីអាង។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. នៅពេល \(t = 0 \Rightarrow V = 500\ \text{L}\) (ទឹកពេញអាង) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8849, 'ដ្យាក្រាមស្រមោលបង្ហាញប្រវែងស្រមោលបង្គោលមួយពីម៉ោង 7h ដល់ 17h។ ក. រកម៉ោងដែលស្រមោលមានប្រវែងវែងជាងគេ។ ខ. រកម៉ោងដែលស្រមោលមានប្រវែងខ្លីជាងគេ។ គ. ពន្យល់មូលហេតុវិទ្យាសាស្ត្រ។', 'g8-9fd123fb39.svg', '[]', 0, NULL, 5, 'writing', 'ក. ស្រមោលវែងជាងគេនៅម៉ោង 7h ព្រឹក និងម៉ោង 17h ល្ងាច (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8850, 'ក្រាបសីតុណ្ហភាពមួយបង្ហាញថាសីតុណ្ហភាពអប្បបរមា \(22^\circ\text{C}\) នៅម៉ោង 5h ព្រឹក និងអតិបរមា \(34^\circ\text{C}\) នៅម៉ោង 14h រសៀល។ ក. គណនាគម្លាតសីតុណ្ហភាពប្រចាំថ្ងៃ។ ខ. ប៉ាន់ស្មានសីតុណ្ហភាពមធ្យមនៃថ្ងៃនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. គម្លាតសីតុណ្ហភាព ៖ \(\Delta T = T_{\max} - T_{\min}\) (1 ពិន្ទុ)
